package com.telecom.tollfree.service;
import com.telecom.tollfree.api.ApiModels.*; import com.telecom.tollfree.domain.*; import com.telecom.tollfree.messaging.*; import com.telecom.tollfree.repository.*; import org.springframework.cache.annotation.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.Instant;
@Service @Transactional public class NumberService { private final TelecomNumberRepository numbers; private final AuditLogRepository audits; private final NumberEventPublisher events; public NumberService(TelecomNumberRepository n,AuditLogRepository a,NumberEventPublisher e){numbers=n;audits=a;events=e;} private NumberView view(TelecomNumber n){return new NumberView(n.getNumber(),n.getStatus(),n.getCustomer()==null?null:n.getCustomer().getId());} public NumberView importNumber(String value){if(numbers.existsById(value))throw new ConflictException("Number already exists");return view(numbers.save(new TelecomNumber(value)));} @Cacheable(cacheNames="number-status",key="#number") @Transactional(readOnly=true) public NumberView status(String number){return view(numbers.findById(number).orElseThrow(()->new NotFoundException("Number not found")));} @Transactional(readOnly=true) public Page<NumberView> search(NumberStatus s,Pageable p){return s==null?numbers.findAll(p).map(this::view):numbers.findByStatus(s,p).map(this::view);} @CacheEvict(cacheNames="number-status",key="#number") public NumberView transition(String number,NumberStatus target){TelecomNumber n=numbers.lockByNumber(number).orElseThrow(()->new NotFoundException("Number not found")); if(!allowed(n.getStatus(),target))throw new ConflictException("Invalid transition from "+n.getStatus()+" to "+target); n.transition(target); if(target==NumberStatus.RELEASED||target==NumberStatus.AVAILABLE)n.clearCustomer(); audits.save(new AuditLog(number,target.name())); String customer=n.getCustomer()==null?null:n.getCustomer().getId(); events.publish(new NumberEvent("Number"+capitalize(target),number,customer,Instant.now())); return view(n);} @CacheEvict(cacheNames="number-status",key="#number") public NumberView reserve(String number,Customer customer){TelecomNumber n=numbers.lockByNumber(number).orElseThrow(()->new NotFoundException("Number not found"));if(n.getStatus()!=NumberStatus.AVAILABLE)throw new ConflictException("Number is not available");n.assign(customer);n.transition(NumberStatus.RESERVED);audits.save(new AuditLog(number,"RESERVED"));events.publish(new NumberEvent("NumberReserved",number,customer.getId(),Instant.now()));return view(n);} private boolean allowed(NumberStatus from,NumberStatus to){return (from==NumberStatus.AVAILABLE&&to==NumberStatus.RESERVED)||(from==NumberStatus.RESERVED&&to==NumberStatus.AVAILABLE)||(from==NumberStatus.RESERVED&&to==NumberStatus.ACTIVE)||(from==NumberStatus.ACTIVE&&to==NumberStatus.SUSPENDED)||(from==NumberStatus.SUSPENDED&&to==NumberStatus.ACTIVE)||(from==NumberStatus.ACTIVE&&to==NumberStatus.RELEASED);} private String capitalize(NumberStatus s){String x=s.name().toLowerCase();return Character.toUpperCase(x.charAt(0))+x.substring(1);} }
